create extension if not exists pgcrypto;
create table if not exists tournaments(id uuid primary key default gen_random_uuid(),name text not null,event_date date,place text,max_teams int default 12,teams_per_pool int default 4,qualified_per_pool int default 2,num_fields int default 1,match_minutes int default 20,warmup_minutes int default 10,start_time time default '09:00',registration_open boolean default true,created_at timestamptz default now());
create table if not exists teams(id uuid primary key default gen_random_uuid(),tournament_id uuid references tournaments(id) on delete cascade,club_name text not null,category text,coach_name text,contact text,status text default 'pending',created_at timestamptz default now());
create table if not exists pools(id uuid primary key default gen_random_uuid(),tournament_id uuid references tournaments(id) on delete cascade,name text not null);
create table if not exists pool_teams(pool_id uuid references pools(id) on delete cascade,team_id uuid references teams(id) on delete cascade,primary key(pool_id,team_id));
create table if not exists matches(id uuid primary key default gen_random_uuid(),tournament_id uuid references tournaments(id) on delete cascade,pool_id uuid references pools(id) on delete set null,stage text default 'pool',label text,home_team_id uuid references teams(id) on delete set null,away_team_id uuid references teams(id) on delete set null,home_score int,away_score int,field int,warmup_time time,match_time time,referee text,table_officials text,status text default 'scheduled',next_match_id uuid references matches(id),next_slot text,created_at timestamptz default now());
alter table tournaments enable row level security;alter table teams enable row level security;alter table pools enable row level security;alter table pool_teams enable row level security;alter table matches enable row level security;
create policy "read tournaments" on tournaments for select using(true);create policy "read teams" on teams for select using(true);create policy "insert teams" on teams for insert with check(true);create policy "read pools" on pools for select using(true);create policy "read pool_teams" on pool_teams for select using(true);create policy "read matches" on matches for select using(true);
alter publication supabase_realtime add table tournaments;alter publication supabase_realtime add table teams;alter publication supabase_realtime add table matches;